package com.example.nativesso.childapp;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public final class Http{public static String post(String url,String body,String dpop)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");c.setRequestProperty("DPoP",dpop);try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}InputStream i=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(i,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}if(c.getResponseCode()>=400)throw new IOException(b.toString());return b.toString();}}
